1	import { memo, useCallback, useMemo, useState, type ChangeEvent, type FormEvent } from 'react';
2	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
3	import { supabase } from '@/lib/supabase';
4	import { useScope } from '@/lib/data';
5	import { Package, ShieldCheck } from '@/components/Icons';
6	import { useAuth } from '@/contexts/AuthContext';
7	import { useAppSettings } from '@/contexts/AppSettingsContext';
8	import { canAdmin } from '@/lib/policy';
9	import { useSupervisors, useUpdateSupervisor } from '@/lib/data';
10	import { notify } from '@/lib/toast';
11	import { useAdminProducts, useSaveMonthlyTarget, useSaveSettings, type CatalogProduct } from '@/lib/screen-data';
12	import { PageTitle } from '@/components/Layout';
13	import { ErrorState, LoadMore, SkeletonList } from '@/components/States';
14	import EmptyState from '@/components/EmptyState';
15	import { MONTHS } from '@/lib/format';
16	import type { Supervisor } from '@/types/database';
17	import CustomersScreen from './CustomersScreen';
18	import { Chip, SelectOption, useInput, useRefetch } from './shared';
19	import { t } from '@/i18n';
20	
21	export const ROLE: Record<string, string> = { admin: t('مدير'), supervisor: t('مشرف'), senior_supervisor: t('مشرف أول'), branch_manager: t('مدير فرع'), super_admin: t('مدير أعلى') };
22	type AssetType = { id: string; name_ar: string; name_en: string | null; icon: string; color: string; requires_qr: boolean; is_active: boolean };
23	
24	function useAssetTypes() {
25	  const sc = useScope();
26	  return useQuery({
27	    queryKey: [...sc.base, 'asset-types'],
28	    queryFn: async () => {
29	      const { data, error } = await supabase.from('asset_types').select('id,name_ar,name_en,icon,color,requires_qr,is_active').eq('company_id', sc.companyId).order('name_ar');
30	      if (error) throw new Error(t('تعذر تحميل أنواع الأصول.'));
31	      return data as AssetType[];
32	    },
33	  });
34	}
35	
36	function useSaveAssetType() {
37	  const sc = useScope(); const qc = useQueryClient();
38	  return useMutation({
39	    mutationFn: async (input: { id?: string; name_ar: string; name_en: string; icon: string; color: string; requires_qr: boolean }) => {
40	      const values = { name_ar: input.name_ar.trim(), name_en: input.name_en.trim(), icon: input.icon.trim(),
41	        color: input.color, requires_qr: input.requires_qr };
42	      if (!values.name_ar || !values.icon || !/^#[0-9a-f]{6}$/i.test(values.color)) throw new Error(t('بيانات نوع الأصل غير صالحة.'));
43	      if (input.id) {
44	        const { data, error } = await supabase.from('asset_types').update(values)
45	          .eq('id', input.id).eq('company_id', sc.companyId).select('id').single();
46	        if (error || !data) throw new Error(t('لم يتم تحديث نوع الأصل. تحقق من وجوده وصلاحية التعديل.'));
47	      } else {
48	        const { error } = await supabase.from('asset_types').insert({ ...values, company_id: sc.companyId });
49	        if (error) throw new Error(t('تعذر إضافة نوع الأصل.'));
50	      }
51	    },
52	    onSuccess: () => { notify(t('تم حفظ نوع الأصل'), 'success'); qc.invalidateQueries({ queryKey: [...sc.base, 'asset-types'] }); },
53	    onError: (e: Error) => notify(e.message, 'error'),
54	  });
55	}
56	
57	export function AssetTypes() {
58	  const q = useAssetTypes(); const m = useSaveAssetType(); const retry = useRefetch(q.refetch);
59	  const [show, setShow] = useState(false); const [edit, setEdit] = useState<AssetType | null>(null);
60	  const [nameAr, setNameAr] = useState(''); const [nameEn, setNameEn] = useState(''); const [icon, setIcon] = useState('📦'); const [color, setColor] = useState('#1A56DB'); const [qr, setQr] = useState(true);
61	  const openNew = useCallback(() => { setEdit(null); setNameAr(''); setNameEn(''); setIcon('📦'); setColor('#1A56DB'); setQr(true); setShow(true); }, []);
62	  const openEdit = useCallback((a: AssetType) => { setEdit(a); setNameAr(a.name_ar); setNameEn(a.name_en ?? ''); setIcon(a.icon); setColor(a.color); setQr(a.requires_qr); setShow(true); }, []);
63	  const close = useCallback(() => setShow(false), []);
64	  const onNameAr = useInput(setNameAr); const onNameEn = useInput(setNameEn); const onIcon = useInput(setIcon); const onColor = useInput(setColor);
65	  const onQr = useCallback((e: ChangeEvent<HTMLInputElement>) => setQr(e.target.checked), []);
66	  const valid = nameAr.trim() && icon.trim() && /^#[0-9a-f]{6}$/i.test(color);
67	  const save = useCallback((e: FormEvent) => { e.preventDefault(); if (!valid) return; m.mutate({ id: edit?.id, name_ar: nameAr, name_en: nameEn, icon, color, requires_qr: qr }, { onSuccess: close }); }, [m, edit, nameAr, nameEn, icon, color, qr, valid, close]);
68	  return <>
69	    <button className="btn sm" onClick={openNew}>{t('+ إضافة نوع أصل')}</button>
70	    {show && <div className="card col"><div className="title">{edit ? t('تعديل نوع الأصل') : t('نوع أصل جديد')}</div>
71	      <form className="col" onSubmit={save}>
72	        <label className="f">{t('الاسم بالعربي *')}<input className="input" value={nameAr} onChange={onNameAr} placeholder={t('ثلاجة عرض')} /></label>
73	        <label className="f">{t('الاسم بالإنجليزي')}<input className="input" value={nameEn} onChange={onNameEn} placeholder="Display Cooler" /></label>
74	        <label className="f">{t('الأيقونة')}<input className="input" value={icon} onChange={onIcon} placeholder="🧊" /></label>
75	        <label className="f">{t('اللون')}<div className="row"><input type="color" value={/^#[0-9a-f]{6}$/i.test(color) ? color : '#1A56DB'} onChange={onColor} style={{ width: 52, height: 48 }} /><input className="input" value={color} onChange={onColor} dir="ltr" /></div></label>
76	        <label className="row" style={{ minHeight: 44 }}><input type="checkbox" checked={qr} onChange={onQr} style={{ width: 24, height: 24 }} /> {t('يتطلب QR Code')}</label>
77	        <div className="row"><button className="btn" disabled={!valid || m.isPending}>{m.isPending ? t('جاري الحفظ...') : t('حفظ')}</button><button type="button" className="btn ghost" onClick={close}>{t('إلغاء')}</button></div>
78	      </form></div>}
79	    {q.isPending ? <SkeletonList n={3} /> : q.isError ? <ErrorState error={q.error} onRetry={retry} /> : !q.data?.length ? <EmptyState icon={<Package />} title={t('لا توجد أنواع أصول')} action={{ label: t('إضافة نوع'), onClick: openNew }} /> :
80	      q.data.map((a) => <div key={a.id} className="card col" style={{ borderRight: `4px solid ${a.color}` }}>
81	        <div className="row between"><div className="row" style={{ gap: 12 }}><span style={{ fontSize: 28 }}>{a.icon}</span><div><div className="title">{a.name_ar}</div>{a.name_en && <div className="muted" dir="ltr">{a.name_en}</div>}</div></div>
82	          <button className="btn sm ghost" onClick={() => openEdit(a)}>{t('تعديل')}</button></div>
83	        <div className="row" style={{ gap: 8 }}>{a.requires_qr && <span className="badge b-blue">{t('يتطلب QR')}</span>}<span className={`badge ${a.is_active ? 'b-green' : 'b-gray'}`}>{a.is_active ? t('نشط') : t('متوقف')}</span></div>
84	      </div>)}
85	  </>;
86	}
87	
88	const TABS = [['sup', t('المشرفون')], ['cus', t('العملاء')], ['pro', t('المنتجات')], ['ast', t('الأصول')], ['set', t('الإعدادات')], ['tar', t('الأهداف')]] as const;
89	type Tab = typeof TABS[number][0];
90	
91	const SupRow = memo(function SupRow({ s, self, onPatch }: { s: Supervisor; self: boolean; onPatch: (s: Supervisor, p: { is_active?: boolean; role?: 'admin' | 'supervisor' }) => void }) {
92	  const locked = self || s.role === 'super_admin';
93	  const toggle = useCallback(() => {
94	    if (!s.is_active || window.confirm(t('تعطيل حساب {name}؟', { name: s.full_name }))) onPatch(s, { is_active: !s.is_active });
95	  }, [s, onPatch]);
