242	/* ---------- Broadcast notifications ---------- */
243	export function AdminNotifications() {
244	  const sups = useSupervisors(); const m = useBroadcast();
245	  const [title, setTitle] = useState(''); const [body, setBody] = useState(''); const [all, setAll] = useState(true);
246	  const [picked, setPicked] = useState<Set<string>>(new Set());
247	  const active = sups.items.filter((s) => s.is_active);
248	  const togglePick = (id: string) => setPicked((p) => { const n = new Set(p); if (n.has(id)) n.delete(id); else n.add(id); return n; });
249	  const submit = useCallback((e: FormEvent) => { e.preventDefault();
250	    const ids = all ? active.map((s) => s.id) : [...picked];
251	    m.mutate({ supervisorIds: ids, title, body }, { onSuccess: () => { setTitle(''); setBody(''); setPicked(new Set()); } });
252	  }, [m, all, active, picked, title, body]);
253	  return <>
254	    <h2>{t('إرسال إشعار')}</h2>
255	    <form className="card col" style={{ maxWidth: 640 }} onSubmit={submit}>
256	      <label className="f">{t('العنوان *')}<input className="input" required maxLength={120} value={title} onChange={useInput(setTitle)} /></label>
257	      <label className="f">{t('النص *')}<textarea className="input" required rows={4} maxLength={1000} value={body} onChange={useInput(setBody)} /></label>
258	      <div className="row"><label className="row"><input type="radio" checked={all} onChange={() => setAll(true)} /> {t('كل المشرفين النشطين ({n})', { n: active.length })}</label>
259	        <label className="row"><input type="radio" checked={!all} onChange={() => setAll(false)} /> {t('مشرفون محددون')}</label></div>
260	      {!all && <div className="row" style={{ flexWrap: 'wrap' }}>{active.map((s) =>
261	        <button type="button" key={s.id} className={`chip ${picked.has(s.id) ? 'on' : ''}`} aria-pressed={picked.has(s.id)} onClick={() => togglePick(s.id)}>{s.full_name}</button>)}</div>}
262	      <LoadMore q={sups} />
263	      <button className="btn" disabled={m.isPending} data-testid="button-broadcast"><Bell size={18} /> {m.isPending ? t('جاري الإرسال...') : t('إرسال')}</button>
264	    </form>
265	  </>;
266	}
