330	function SurveyForm({ edit, onClose }: { edit: SurveyRow | null; onClose: () => void }) {
331	  const m = useSaveSurvey();
332	  const [title, setTitle] = useState(edit?.title ?? '');
333	  const [targetType, setTargetType] = useState(edit?.target_customer_type ?? '');
334	  const [mandatory, setMandatory] = useState(edit?.is_mandatory ?? false);
335	  const [active, setActive] = useState(edit?.is_active ?? true);
336	  const [validFrom, setValidFrom] = useState(edit?.valid_from?.slice(0, 10) ?? '');
337	  const [validTo, setValidTo] = useState(edit?.valid_to?.slice(0, 10) ?? '');
338	  const [questions, setQuestions] = useState<SurveyQuestion[]>(edit?.questions ?? []);
339	  const addQ = useCallback(() => setQuestions((q) => [...q, { text: '', type: 'text' }]), []);
340	  const removeQ = useCallback((i: number) => setQuestions((q) => q.filter((_, idx) => idx !== i)), []);
341	  const updateQ = useCallback((i: number, field: keyof SurveyQuestion, val: string) =>
342	    setQuestions((q) => q.map((item, idx) => idx === i ? { ...item, [field]: val } : item)), []);
343	  const submit = useCallback((e: FormEvent) => { e.preventDefault();
344	    m.mutate({ id: edit?.id, title, questions, target_customer_type: targetType,
345	      is_mandatory: mandatory, is_active: active, valid_from: validFrom, valid_to: validTo }, { onSuccess: onClose });
346	  }, [m, edit, title, questions, targetType, mandatory, active, validFrom, validTo, onClose]);
347	  return <Modal title={edit ? t('تعديل الاستبيان') : t('استبيان جديد')} onClose={onClose} onSubmit={submit}>
348	    <label className="f">{t('عنوان الاستبيان *')}<input className="input" required value={title} onChange={useInput(setTitle)} /></label>
349	    <div className="row">
350	      <label className="f grow">{t('نوع العميل المستهدف')}<input className="input" placeholder={t('الكل')} value={targetType} onChange={useInput(setTargetType)} /></label>
351	    </div>
352	    <div className="row">
353	      <label className="f grow">{t('من تاريخ')}<input className="input" type="date" value={validFrom} onChange={useInput(setValidFrom)} /></label>
354	      <label className="f grow">{t('إلى تاريخ')}<input className="input" type="date" value={validTo} onChange={useInput(setValidTo)} /></label>
355	    </div>
356	    <div className="row" style={{ gap: 24 }}>
357	      <label className="row"><input type="checkbox" checked={mandatory} onChange={(e) => setMandatory(e.target.checked)} style={{ width: 20, height: 20 }} /> {t('إلزامي')}</label>
358	      <label className="row"><input type="checkbox" checked={active} onChange={(e) => setActive(e.target.checked)} style={{ width: 20, height: 20 }} /> {t('نشط')}</label>
359	    </div>
360	    <div className="title" style={{ marginTop: 8 }}>{t('الأسئلة')}</div>
361	    {questions.map((q, i) => <div key={i} className="card col" style={{ gap: 6, padding: '10px 12px' }}>
362	      <div className="row between">
363	        <span className="muted" style={{ fontSize: 12 }}>{t('سؤال')} {i + 1}</span>
364	        <button type="button" className="icon-btn" onClick={() => removeQ(i)}><X size={16} /></button>
365	      </div>
366	      <input className="input" placeholder={t('نص السؤال *')} value={q.text}
367	        onChange={(e) => updateQ(i, 'text', e.target.value)} required />
368	      <select className="input" value={q.type} onChange={(e) => updateQ(i, 'type', e.target.value)}>
369	        <option value="text">{t('نص حر')}</option>
370	        <option value="rating">{t('تقييم (1-5)')}</option>
371	        <option value="choice">{t('اختيار من متعدد')}</option>
372	      </select>
373	    </div>)}
374	    <button type="button" className="btn ghost" onClick={addQ}><Plus size={16} /> {t('إضافة سؤال')}</button>
375	    <button className="btn" disabled={m.isPending || !questions.length}>
376	      {m.isPending ? t('جاري الحفظ...') : t('حفظ')}</button>
377	  </Modal>;
