385	    {q.isPending ? <SkeletonList /> : q.isError ? <ErrorState error={q.error} onRetry={retry} />
386	      : !q.data?.length ? <EmptyState icon={<FileText />} title={t('لا توجد استبيانات')} action={{ label: t('إنشاء استبيان'), onClick: () => setEdit(null) }} />
387	      : <div className="adm-table-wrap"><table className="adm-table">
388	          <thead><tr><th>{t('العنوان')}</th><th>{t('الأسئلة')}</th><th>{t('الفترة')}</th><th>{t('الحالة')}</th><th /></tr></thead>
389	          <tbody>{q.data.map((s) => <tr key={s.id}>
390	            <td><div className="title">{s.title}</div>{s.is_mandatory && <span className="badge b-red" style={{ fontSize: 11 }}>{t('إلزامي')}</span>}</td>
391	            <td>{s.questions.length}</td>
392	            <td style={{ fontSize: 12, direction: 'ltr', textAlign: 'start' }}>
393	              {s.valid_from ? `${s.valid_from.slice(0, 10)} → ${s.valid_to?.slice(0, 10) ?? '∞'}` : '—'}</td>
394	            <td><span className={`badge ${s.is_active ? 'b-green' : 'b-gray'}`}>{s.is_active ? t('نشط') : t('متوقف')}</span></td>
395	            <td><button className="btn sm ghost" onClick={() => setEdit(s)}>{t('تعديل')}</button></td>
396	          </tr>)}</tbody>
397	        </table></div>}
398	    {edit !== undefined && <SurveyForm edit={edit} onClose={() => setEdit(undefined)} />}
399	  </>;
