402	/* ---------- Company settings + logo ---------- */
403	export function AdminSettings() {
404	  const s = useAppSettings(); const up = useUploadLogo(); const save = useSaveSettings();
405	  const onLogo = useCallback(async (e: ChangeEvent<HTMLInputElement>) => {
406	    const file = e.target.files?.[0]; e.target.value = '';
407	    if (!file) return;
408	    const url = await up.mutateAsync(file).catch(() => null);
