410	      target_brand_name: s.target_brand_name, competitor_brands: s.competitor_brands, logo_url: url });
411	  }, [up, save, s]);
412	  return <>
413	    <h2>{t('إعدادات الشركة')}</h2>
414	    <div className="adm-grid">
415	      <SettingsForm />
416	      <div className="card col">
417	        <div className="title">{t('شعار الشركة')}</div>
418	        {s.logo_url ? <img src={s.logo_url} alt={t('شعار الشركة')} style={{ maxWidth: 160, maxHeight: 160, objectFit: 'contain' }} /> : <div className="muted">{t('لا يوجد شعار.')}</div>}
419	        <label className="btn ghost">{up.isPending || save.isPending ? t('جاري الرفع...') : t('رفع شعار جديد')}
420	          <input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" hidden onChange={onLogo} data-testid="input-logo" /></label>
421	        <div className="muted" style={{ fontSize: 13 }}>{t('PNG أو JPG أو WEBP أو SVG · حتى 1 ميجابايت')}</div>
422	      </div>
423	    </div>
424	  </>;
425	}
