.btn:active{transform:scale(.97)}.btn:disabled{opacity:.5;cursor:not-allowed}
.btn.ghost{background:#fff;color:var(--color-primary);border-color:var(--color-primary)}
.btn.success{background:var(--color-success);color:#fff}.btn.danger{background:var(--color-danger);color:#fff}
.btn.danger-ghost{background:#fff;color:var(--color-danger);border-color:var(--color-danger)}
.btn.sm{min-height:44px;padding:0 12px;font-size:14px}.btn.block{width:100%}
.icon-btn{min-height:44px;min-width:44px;display:grid;place-items:center;border-radius:12px;background:transparent;border:0;color:inherit;cursor:pointer;position:relative}
.input{width:100%;min-height:48px;border:2px solid var(--line);border-radius:12px;padding:8px 12px;font:inherit;font-size:16px;background:#fff;color:var(--ink)}
.input:focus{outline:none;border-color:var(--color-primary)}
label.f{display:flex;flex-direction:column;gap:4px;font-weight:600;font-size:14px}
.badge{display:inline-flex;align-items:center;min-height:26px;padding:0 10px;border-radius:99px;font-size:13px;font-weight:700;white-space:nowrap}
.b-green{background:#D1F2EA;color:#0B5F59}.b-yellow{background:#FDF0C2;color:#7A4A04}.b-red{background:#FDE0E0;color:#A61B1B}.b-blue{background:#DCE8FD;color:#1344A8}.b-gray{background:#E8ECF2;color:#3D4B5C}
.tabs{display:flex;gap:8px;overflow-x:auto;padding-bottom:2px;scrollbar-width:none}
.chip{min-height:44px;padding:0 16px;border-radius:99px;border:2px solid var(--line);background:#fff;font:inherit;font-weight:600;white-space:nowrap;cursor:pointer;color:var(--ink)}
.chip.on{background:var(--color-primary);border-color:var(--color-primary);color:var(--primary-foreground)}
.kpis{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.kpi{background:#fff;border:1px solid var(--line);border-radius:14px;padding:12px;display:flex;flex-direction:column;gap:6px;border-inline-start:5px solid var(--kc,var(--color-primary))}
.kpi .ic{color:var(--kc,var(--color-primary))}
.skel{background:linear-gradient(90deg,#E8ECF2 25%,#F3F5F9 50%,#E8ECF2 75%);background-size:200% 100%;animation:sh 1.2s infinite;border-radius:8px;min-height:18px}
@keyframes sh{to{background-position:-200% 0}}
.bar{height:12px;border-radius:99px;background:#E8ECF2;overflow:hidden}.bar>i{display:block;height:100%;background:var(--color-primary);border-radius:99px}
.bottomnav{position:fixed;bottom:0;inset-inline:0;margin-inline:auto;max-width:430px;z-index:30;background:#fff;border-top:1px solid var(--line);display:grid;grid-template-columns:repeat(5,1fr);padding-bottom:var(--sab)}
.bottomnav a{min-height:var(--bottom-nav-height);min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;font-size:12px;font-weight:600;color:var(--muted);text-decoration:none;position:relative}
.bottomnav a.active{color:var(--color-primary)}
.bottomnav a.active::before{content:"";position:absolute;top:0;width:34px;height:4px;border-radius:0 0 4px 4px;background:var(--color-primary)}
.dot{position:absolute;top:6px;inset-inline-start:calc(50% + 6px);min-width:18px;height:18px;border-radius:9px;background:var(--color-danger);color:#fff;font-size:11px;font-weight:700;display:grid;place-items:center;padding:0 4px}
.fab{position:fixed;bottom:calc(76px + var(--sab));inset-inline-start:max(16px,calc(50% - 199px));z-index:25;box-shadow:0 6px 16px rgba(15,27,45,.25);border-radius:99px}
.empty{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;padding:32px 16px;color:var(--muted)}
.empty .ring{width:72px;height:72px;border-radius:50%;background:#E8ECF2;display:grid;place-items:center;color:var(--color-primary)}
.alert{border-radius:12px;padding:12px;font-size:14px;font-weight:600}.alert.err{background:#FDE0E0;color:#8E1616}.alert.warn{background:var(--warn-bg);color:var(--warn)}.alert.ok{background:#D1F2EA;color:#0B5F59}
.sheet-bg{position:fixed;inset:0;background:rgba(15,27,45,.55);z-index:50;display:flex;align-items:flex-end;justify-content:center}
.sheet{background:#fff;width:100%;max-width:430px;max-height:92dvh;overflow:auto;border-radius:20px 20px 0 0;padding:16px 16px calc(16px + var(--sab));animation:up .2s ease-out}
@keyframes up{from{transform:translateY(40px);opacity:0}}
.toasts{position:fixed;top:calc(8px + var(--sat));inset-inline:0;margin-inline:auto;max-width:430px;z-index:80;padding:0 12px;display:flex;flex-direction:column;gap:8px;pointer-events:none}
.toast{pointer-events:auto;padding:12px 14px;border-radius:12px;color:#fff;font-weight:600;box-shadow:0 6px 18px rgba(0,0,0,.25);background:var(--ink)}
.toast.success{background:#108981}.toast.error{background:#EF4444}
.toast.info{background:#1A56DB}.toast{animation:toast-slide-in .2s ease-out}
@keyframes toast-slide-in{from{transform:translateY(-24px);opacity:0}to{transform:translateY(0);opacity:1}}
.scrollbar-hide{-ms-overflow-style:none;scrollbar-width:none}
.scrollbar-hide::-webkit-scrollbar{display:none}
.safe-bottom{padding-bottom:env(safe-area-inset-bottom,16px)}
button,a,input,select,textarea{transition:background-color .15s,color .15s,border-color .15s,box-shadow .15s,transform .1s}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
.loading-screen{min-height:100dvh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;background:var(--color-bg);color:var(--muted);font-weight:600}
.loading-spinner{width:44px;height:44px;border-radius:50%;border:5px solid #D5DCE6;border-top-color:var(--color-primary);animation:spin .8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.settings-error{min-height:100dvh;max-width:430px;margin:auto;padding:32px 20px;display:flex;flex-direction:column;gap:12px;justify-content:center;background:var(--color-bg)}
.settings-error button{min-height:48px;border-radius:12px;border:2px solid var(--color-primary);background:#fff;color:var(--color-primary);font:inherit;font-weight:700}
.login{min-height:100dvh;max-width:430px;margin:auto;display:flex;flex-direction:column;background:var(--color-bg)}
.login .hero{background:var(--color-primary);color:#fff;padding:calc(48px + var(--sat)) 24px 56px;border-radius:0 0 36px 36px;position:relative;overflow:hidden}
.login .hero::after{content:"";position:absolute;inset-inline-end:-60px;bottom:-70px;width:200px;height:200px;border-radius:50%;border:34px solid rgba(255,255,255,.12)}
.login .hero h1{font-size:40px;margin:12px 0 0;line-height:1.1}
.login form{padding:24px;display:flex;flex-direction:column;gap:14px}
.sep{height:1px;background:var(--line);border:0;margin:0}

