.adm-drawer{position:fixed;inset-block:0;inset-inline-start:0;width:min(400px,100%);background:#fff;z-index:51;padding:16px;overflow:auto;box-shadow:0 0 30px rgba(0,0,0,.25);animation:adm-in .2s ease-out}
