29	export function useScope() {
30	  const { supervisor } = useAuth();
31	  const s = supervisor as Supervisor;
32	  return useMemo(() => {
33	    if (!s) throw new Error('بيانات المشرف غير جاهزة. أعد تسجيل الدخول.');
34	    const isAdmin = canAdmin(s);
35	    const base = ['mydan', s.company_id, s.id, s.role] as const;
36	    const scope = (q: any, field = 'supervisor_id') => { q = q.eq('company_id', s.company_id); return isAdmin ? q : q.eq(field, s.id); };
37	    return { supervisor: s, companyId: s.company_id, supervisorId: s.id, isAdmin, base, scope };
38	  }, [s]);
39	}
40	type Scope = ReturnType<typeof useScope>;
41	const inv = (qc: QueryClient, sc: Scope, ...names: string[]) =>
42	  Promise.all(names.map((n) => qc.invalidateQueries({ queryKey: [...sc.base, n] })));
43	
44	export function usePaged<T>(sc: Scope, name: string, params: unknown[],
45	  load: (from: number, to: number, signal: AbortSignal) => Promise<T[]>, enabled = true) {
46	  const q = useInfiniteQuery({
47	    queryKey: [...sc.base, name, ...params], enabled, initialPageParam: 0,
48	    queryFn: ({ pageParam, signal }) => load(pageParam, pageParam + PAGE - 1, signal),
49	    getNextPageParam: (last, all) => last.length === PAGE ? all.length * PAGE : undefined,
50	    retry: 1,
51	    refetchInterval: (query) => name === 'audits'
52	      && query.state.data?.pages.some(page => page.some(row => (row as ShelfAudit).status === 'processing'))
