271	export function useSubmitAudit() {
272	  const sc = useScope(); const qc = useQueryClient();
273	  return useMutation({
274	    mutationFn: async ({ visit, file }: { visit: VisitRow; file: File }) => {
275	      if (!file.type.startsWith('image/')) throw new Error('الملف المختار ليس صورة.');
276	      if (file.size > 10 * 1024 * 1024) throw new Error('حجم الصورة أكبر من 10 ميجابايت.');
277	      const ext = (file.name.split('.').pop() || 'jpg').toLowerCase().replace(/[^a-z0-9]/g, '');
278	      const path = `${sc.companyId}/${sc.supervisorId}/${visit.id}-${Date.now()}.${ext}`;
279	      const up = await supabase.storage.from(PHOTO_BUCKET).upload(path, file, { contentType: file.type });
280	      if (up.error) fail(t('تعذر رفع الصورة. تأكد من وجود الحاوية "{bucket}" وصلاحياتها.', { bucket: PHOTO_BUCKET }), up.error);
281	      const { error, status } = await supabase.from('shelf_audit').insert({
282	        visit_id: visit.id, supervisor_id: sc.supervisorId, company_id: sc.companyId, photo_url: path, status: 'pending',
283	      });
284	      if (error) {
285	        // Only remove an object after a definite rejection. A timeout or lost
286	        // response can occur after a successful insert; preserve its photo.
287	        if (status >= 400 && status < 500 && status !== 408) {
288	          const cleanup = await supabase.storage.from(PHOTO_BUCKET).remove([path]);
289	          if (cleanup.error) fail('تعذر حفظ سجل المراجعة وتعذر حذف الصورة غير المرتبطة.', cleanup.error);
290	          fail('تعذر حفظ سجل المراجعة؛ أزيلت الصورة غير المرتبطة.', error);
291	        }
292	        fail('تم رفع الصورة لكن لم يتأكد حفظ سجل المراجعة. احتُفظ بالصورة لتجنب حذف ملف قد يكون مرتبطًا بسجل محفوظ.', error);
293	      }
294	    },
295	    onSuccess: () => { notify('تم حفظ صورة الرف', 'success'); void inv(qc, sc, 'audits'); },
296	    onError: (e: Error) => notify(e.message, 'error'),
297	  });
298	}
